import{calculator,CalcError}from './core.js?ver=43e079bb5e';import{solar_from_loads}from './solar.js?ver=43e079bb5e';import{MONTH_NAMES,MONTH_DAYS}from './months.js?ver=43e079bb5e';
export const solar_offgrid=calculator((i,d)=>{const r=solar_from_loads.raw({...i,off_grid:true},d);const pv=d?.cities?.[String(i.city??'').trim().toLowerCase()]?.pvout_month;if(!pv)return r;if(pv.length !==12)throw new CalcError('city_unknown','city');const day=pv.map((p,m)=>(r.installed_kw*p)/MONTH_DAYS[m]);const w=day.indexOf(Math.min(...day));const short=Math.max(0,r.array_kwh-day[w]);return{...r,worst_month:MONTH_NAMES[w],worst_month_kwh:day[w],worst_short_kwh:short,worst_short_pct:(short/r.array_kwh)*100,months_short:day.filter((x)=>x<r.array_kwh-1e-9).length};});
